function taskRow(t){return '<div class="task"><span class="iconbox">'+icon(nav.find(n=>n[0]===t.page)?.[2])+'</span><div class="taskbody"><button class="link" data-open="'+t.page+'" data-id="'+t.id+'">'+esc(t.name)+'</button><small>'+esc(t.owner||'ยังไม่มอบหมาย')+' · '+fmt(t.due)+'</small></div>'+badge(t.due<today()?'เกินกำหนด':t.due===today()?'วันนี้':'ใกล้ครบกำหนด')+'</div>'}
function table(head,rows){return '<div class="tablewrap"><table><thead><tr>'+head.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+ (rows.length?rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="'+head.length+'" class="empty">ไม่พบข้อมูลที่ตรงกับเงื่อนไข</td></tr>')+'</tbody></table></div>'}
