if(page==='people'){heads=['รหัส / ชื่อผู้รับบริการ','อายุ','ชุมชน','กลุ่มผู้รับบริการ','จัดการ'];rows=items.map(p=>['<span class="avatar">'+p.name[0]+'</span>'+open(p,p.name)+'<small>'+p.id+'</small>',p.age+' ปี',esc(p.community),badge(p.group),'<button class="link" data-edit="'+p.id+'">แก้ไข</button>'])}
if(page==='visits'){heads=['ผู้รับบริการ','วันนัด / เยี่ยมจริง','เจ้าหน้าที่','สถานะ','จัดการ'];rows=items.map(v=>[open(v,state.people.find(p=>p.id===v.personId)?.name),fmt(v.due)+'<small>'+fmt(v.actual)+'</small>',esc(v.owner),badge(v.status),'<button class="link" data-edit="'+v.id+'">บันทึกผล</button>'])}
