if(page==='establishments'){heads=['สถานประกอบการ','ประเภท','ชุมชน','กำหนดแก้ไข','สถานะ'];rows=items.map(e=>[open(e,e.name),esc(e.type),esc(e.community),fmt(e.deadline),badge(e.status)])}
